-- NOH3 (New Orleans H3) imported calendar history cleanup (2026-11-13).
-- Every row here came from the one-off calendar history import and has no
-- RawEvent, so no scrape will touch it again. Generated read-only from prod.
--
-- 1. One UPDATE over a JSON list of 1,369 Events, keyed by id. Each row
--    changes only the fields it flags (set_*), and only when the old value
--    still matches (md5 or exact), so a row edited since 2026-11-13 is
--    skipped instead of overwritten. Re-running is a no-op.
--    a. 1,366 titles (2011 → 2025-05) that held the whole announcement
--       ("NOH3 Run #1199. Hares: … LOC: … 6:00pm Show / 6:30 GO. Cost $6 …")
--       become the run or social name, plus a short theme or "@ venue" when
--       the text gives one: "NOH3 Run #1465 – Labor Day Hash",
--       "NOH3 Social @ Tarpon Joe's". The full original text moves to the
--       description: 1,181 had none; 139 get it on top of what they had.
--    b. 601 empty haresText filled from "Hares: …" or "X (trail), Y (beer)".
--    c. 8 duplicate run numbers cleared on the row that doesn't fit the
--       weekly sequence (#137, #1215, #1229, #1384, #1412, #1443, #1713,
--       #1799 — the last is "Trail# 1799.5", a half run). 2015-08-31
--       "#1412 Moved to Saturday August 29!" is also marked CANCELLED.
-- 2. 21 Voodoo H3 runs filed under noh3 (2010 weekly "VooDoo #125 …" →
--    #162, and the 2011–13 Voodoo Black Dress Runs) move to voodoo-h3. None
--    shares a date or run number with an existing voodoo-h3 event. Joint
--    NOH3 + Voodoo socials stay on noh3.

-- 1. Field fixes, one row per Event (see header).
UPDATE "Event" e SET
  "title"        = CASE WHEN v.set_title  THEN v.title                 ELSE e."title"        END,
  "haresText"    = CASE WHEN v.set_hares  THEN v.hares                 ELSE e."haresText"    END,
  "runNumber"    = CASE WHEN v.set_run    THEN v.run_number            ELSE e."runNumber"    END,
  "description"  = CASE WHEN v.set_desc   THEN v.description           ELSE e."description"  END,
  "status"       = CASE WHEN v.set_status THEN v.status::"EventStatus" ELSE e."status"       END,
  "updatedAt"    = NOW() AT TIME ZONE 'UTC'
FROM jsonb_to_recordset(
$rows$[{"id":"cmpr8gnp60083pyhng4mu5dki","set_run":true,"run_number":null,"old_run":137},{"id":"cmpr8hg1j00ekpyhnneo0qe0x","set_title":true,"title":"Hash Social – NOH3 & Voodoo group social","old_title_md5":"c9ac3377693c7b921a665827abc7b7aa","set_desc":true,"description":"Hash Social: NOH3 & Voodoo group social. LOC: Twelve Mile Limit Bar. Cost: Free to hashers. 5:30pm\n\n1st NOH3 & Voodoo H3 group social. NOH3 is sponsoring keg.\nIt is a block off of Banks St. (which makes it One Block from Finn Mc Cools) Between Banks and Tulane!","old_desc_md5":"04d07bd47afa84ba05a8d9177f6c4e0b"},{"id":"cmpr8hh3600espyhntwo4dewv","set_title":true,"title":"NOH3 Hash Run #1173","old_title_md5":"b432ff49c883681af2be36d3647d7379","set_hares":true,"hares":"Piston Penis and Boner Lisa","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1173. Hares: Piston Penis and Boner Lisa. LOC: N.Lopez & Esplanade. Cost $6. TIME: 11:30 Show / 12:00 Go\n\nWe are ready for the Cubes, meet at N Lopez & Esplanade\nfor a breakfast hash 11:30 show noon go","old_desc_md5":"83064ce630a391cf9ee89573155187e8"},{"id":"cmpr8hhju00ewpyhneukpit9l","set_title":true,"title":"NOH3 Hash Social","old_title_md5":"f5570800a0cc9954d151077c64c9011a","set_desc":true,"description":"NOH3 Hash Social. Loc: Abita Bock Pub Crawl 5:30 The Bulldog 3236 Magazine St New Orleans\n\nStop 2 Balcony Bar 3201 Magazine St 8pm-9:30pm.\nStop 3 Rendezvous 3101 Magazine St 9:30pm-11pm","old_desc_md5":"5ba802432e716c2bc82a5bb7e8fd7c6b"},{"id":"cmpr8hhur00eypyhnu74b4zya","set_title":true,"title":"NOH3 Hash Run #1174","old_title_md5":"df7bb86e7cc7d4ec05a131ea4fd389a5","set_hares":true,"hares":"Penis Colada & Swamp Bitch","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1174. Hares: Penis Colada & Swamp Bitch. LOC: Destrehan/Luling Bridge. 12:00 Show / 12:30 GO. Cost $6.\n\nThe hash this Sunday is in the park under the Destrehan Bridge. From New Orleans take the I-10 west to the I-310 go to the last exit before you cross the bridge. It is exit 6 to Destrehan. When you come off of the exit take a right onto River Road and the park is right there under the bridge. The Wall is Sunday Morning at 8:00. It is a 30k, 18 mile run, for people that are training for a marathon. There is also a 10k if you are training for a half marathon. The hash is meeting at 12:00 and running at 12:30. You can come out early & socialize with the runners & help them empty their kegs before we tap into the hash beer. Yes we will have plenty of cold beer and good food provided by the hares, Penis Colada and Swamp Bitch. We might even have a mystery hare. It is a $6 hash with beer, good food, beer, shiggy, beer, nice trail and beer. Cum on out and expect to have a good time with your fellow hashers. This is one that you will talk about for minutes, I mean years to cum!","old_desc_md5":"a554f75570abe744e0a0af107ccddc1e"},{"id":"cmpr8hij300f4pyhnpflwmrxc","set_title":true,"title":"NOH3 Hash Run #1175","old_title_md5":"e79fac8cace4cf51f48ed60f186a39a7","set_hares":true,"hares":"Spread Em","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1175. Hares: Spread Em. LOC: Bayou Bicycles. meet on the bayou. 2:00 Show / 2:30 GO. Cost $5\n\nOn After: Free beer only for those who run the hash. Bayou Beer Garden to watch Super Bowl. Bring your own meat to cook on their grill. Address: 326 N Jefferson Davis Pkwy NOLA 70119","old_desc_md5":"3f9bb9b02db6ad02017e0448fad01509"},{"id":"cmpr8hj0c00f8pyhnylyj60bj","set_title":true,"title":"NOH3 Social 6pm – Turtle Bay on Decatur","old_title_md5":"5a630b8c32ad875b6e71fe48866a61f8","set_desc":true,"description":"NOH3 Social 6pm. Turtle Bay on Decatur. Then Toast to \"G\" 7:30pm Cafe Pontalba Jackson Square.\n\nOk so it appears that some out of town hashers are planning a social for us locals on Friday 02/11/2011 to toast to \"G's\" memory in Jackson Square, 7:30pm. Meet at Turtle Bay around 6pm. From there they will go to Cafe Pontalba for 7:30pm for the toast.","old_desc_md5":"7718c68fb8de14a2eb1b5defcd16a7e4"},{"id":"cmpr8hjd700fapyhnueqzyov3","set_title":true,"title":"NOH3 Hash Run #1176","old_title_md5":"675052d480b2fe160211be2b7aadb05f","set_hares":true,"hares":"Piston Penis and Boner Lisa","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1176. Hares: Piston Penis and Boner Lisa. LOC: Esplanade Ave & N Derbigny. 11am Show. Cost $6. Red Dress Water Station for Rock N Roll Marathon & 1/2 Marathon meet 7am\n\nRock N Roll Mardi Gras Marathon. RED DRESS WATER STATION. Miles 10 &13. Red Dress Mandatory. Hash will be after the Marathon is over.\nHash will meet at 11:00 am at N Derbigny and Esplanade. that is 1 block off Claiborne near (I-10). towards city park on Esplanade. COST for hash $6. but if you show early, and we mean 7am, to volunteer, then the cost is only $1.\nOn-After: chikiee waa waa for more partying.","old_desc_md5":"71ec2f3617b599f808209e24dde54118"},{"id":"cmpr8hk8100fipyhnutn4udme","set_title":true,"title":"NOH3 Hash Run #1177","old_title_md5":"24bb256ad81fd887cb361372d873e95f","set_hares":true,"hares":"Purrfurred Pussy, Toe Hoe, G-String, Came Upon Me, Tasty Meat","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1177. Hares: Purrfurred Pussy, Toe Hoe, G-String, Came Upon Me, Tasty Meat. LOC: Lafayette Square. 11:00am Show / 11:30 GO. Cost $6\n\nPurrfurred Pussy's Birthday Hash. Let's make her a cake!","old_desc_md5":"421ae6ad73412b2700f1b8827cb7340b"},{"id":"cmpr8hkvx00fopyhnjogmvhx0","set_title":true,"title":"NOH3 Hash Run #1178","old_title_md5":"5755227d305a561f68343e4845543e1e","set_hares":true,"hares":"Came Upon Me & Lick a Lotta Cock (Virgin Hare)","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1178; Hares: Came Upon Me & Lick a Lotta Cock (Virgin Hare). LOC: parking lot near Armstrong Park - Barkus Parade. 11:00am Show / 11:30am GO. Cost $6.\n\nBarkus begins 2pm near Armstrong Park at N. Rampart & Orleans. Dogs ON LEASH are welcome to the hash.\n\nThere's discounted parking of $15 at the parking lot bounded by Marais, St Louis and Basin in front of the old orange market. Tell the attendant the password \"Broadway Tails\" if you plan on staying for the Barkus parade and are looking for safe parking. Or find something on the street for FREE.","old_desc_md5":"4fb481481fbd01e4b4a1ee216d309109"},{"id":"cmpr8hlda00fspyhnlbxcae1k","set_title":true,"title":"NOH3 – Mardi Gras Madness 21","old_title_md5":"08d77d9d41116d2f346b0a31a908f1e2","set_desc":true,"description":"NOH3: Mardi Gras Madness 21. Checkin 4pm - 8pm. Cost $50. Pub Crawl begins at 6:30pm\n\nRegistration/Check-in Friday 4-8pm. Pub Crawl leaves at 6:30. List of bars are at the hotel room 816.","old_desc_md5":"7c8b79e6b544b33380ee325bd229dd2e"},{"id":"cmpr8hln900fupyhn6cpxvtof","set_title":true,"title":"NOH3 Hash Run #1179","old_title_md5":"0c49dbae6199b49a41f3a4b3ab7450c4","set_hares":true,"hares":"Incocknito","old_hares_md5":null,"set_desc":true,"description":"NOH3 Hash Run #1179. Hares: Incocknito. LOC: Holiday Inn on Loyola. Hares Away at 10am. see below for more details. Cost late registrants $50\n\nBreakfast and Registration 7:30-10:00.\nCostume Contest 9-10am\nHares Away 10:00am.","old_desc_md5":"a151a1ddba3cdf8de7fef7cd2d70ad74"},{"id":"cmpr8hmvo00g6pyhnlwqvidy5","set_title":true,"title":"Green Dress Run – NOH3 Hash Run #1180","old_title_md5":"397486eb89424ef6defff91c0f8d3888","set_hares":true,"hares":"Tidy Bowl, Little Red Head, We'd Eat Her","old_hares_md5":null,"set_desc":true,"description":"Green Dress Run!!! NOH3 Hash Run #1180. Hares: Tidy Bowl, Little Red Head, We'd Eat Her. LOC: 2350 Metairie Road Metairie, LA 70001. $6 hash. 10am show / 10:30am Go!\n\nGreen Dress Run. Metaire St. Patricks Parade. We're cooking authentic Irish something or other and there will be a keg of O'Lite and O'Amber on tap. Be sure to dress for success as we'll be having a costume strut-off just like last year. Cartwheels welcome.","old_desc_md5":"72fe64f9a909