) AS v(
  id text,
  set_title boolean, title text, old_title_md5 text,
  set_hares boolean, hares text, old_hares_md5 text,
  set_run boolean, run_number integer, old_run integer,
  set_desc boolean, description text, old_desc_md5 text,
  set_status boolean, status text, old_status text
)
WHERE e."id" = v.id
  AND (v.set_title  IS NOT TRUE OR md5(e."title") = v.old_title_md5)
  AND (v.set_hares  IS NOT TRUE OR md5(e."haresText") IS NOT DISTINCT FROM v.old_hares_md5)
  AND (v.set_run    IS NOT TRUE OR e."runNumber" IS NOT DISTINCT FROM v.old_run)
  AND (v.set_desc   IS NOT TRUE OR md5(e."description") IS NOT DISTINCT FROM v.old_desc_md5)
  AND (v.set_status IS NOT TRUE OR e."status"::text = v.old_status);

-- 2. Move Voodoo H3's own runs from noh3 to voodoo-h3 (re-attribute, never
--    delete). Only rows still primary on noh3 move; a voodoo-h3 EventKennel
--    row that already exists is promoted instead of duplicated.
CREATE TEMP TABLE noh3_voodoo ON COMMIT DROP AS
SELECT e.id
FROM "Event" e
JOIN "Kennel" k ON k.id = e."kennelId"
WHERE k."kennelCode" = 'noh3'
  AND e.id IN (SELECT jsonb_array_elements_text(
$ids$["cmpr8gcbi005lpyhnqicmusq4","cmpr8gdad005tpyhnmtzl73r6","cmpr8gebm0061pyhnb9p6976e","cmpr8gju20077pyhnwnqr0v9h","cmpr8gkub007fpyhnk7j9r9ob","cmpr8glmy007lpyhnd215fglc","cmpr8gmq2007vpyhnbsl9m1za","cmpr8gnp60083pyhng4mu5dki","cmpr8grct008xpyhn6yauuud7","cmpr8gsa90095pyhnpobs3npx","cmpr8gt5o009dpyhnn3lwl4p4","cmpr8gvtd009xpyhnvegpfoqe","cmpr8gwzi00a5pyhncob8caso","cmpr8gym000aipyhn1hnajo78","cmpr8gz8000aopyhnrsymzlov","cmpr8h09400awpyhne9qb0sa8","cmpr8h18k00b4pyhnwobqbn75","cmpr8h8v600cqpyhnnqauk9s6","cmpr8i9xa00m8pyhn535htjif","cmpr8janb00u1pyhn3bmvbm8b","cmpr8k6ka010dpyhnz7qsimqs"]$ids$::jsonb));

DELETE FROM "EventKennel" ek
USING "Kennel" ok, "Kennel" nk
WHERE ok."kennelCode" = 'noh3' AND nk."kennelCode" = 'voodoo-h3'
  AND ek."kennelId" = ok.id
  AND ek."eventId" IN (SELECT id FROM noh3_voodoo)
  AND EXISTS (SELECT 1 FROM "EventKennel" x WHERE x."eventId" = ek."eventId" AND x."kennelId" = nk.id);

UPDATE "EventKennel" ek
SET "isPrimary" = true
FROM "Kennel" nk
WHERE nk."kennelCode" = 'voodoo-h3' AND ek."kennelId" = nk.id
  AND ek."eventId" IN (SELECT id FROM noh3_voodoo) AND ek."isPrimary" = false;

UPDATE "EventKennel" ek
SET "kennelId" = nk.id
FROM "Kennel" nk, "Kennel" ok
WHERE nk."kennelCode" = 'voodoo-h3' AND ok."kennelCode" = 'noh3'
  AND ek."kennelId" = ok.id
  AND ek."eventId" IN (SELECT id FROM noh3_voodoo);

UPDATE "Event" e
SET "kennelId" = nk.id, "updatedAt" = NOW() AT TIME ZONE 'UTC'
FROM "Kennel" nk
WHERE nk."kennelCode" = 'voodoo-h3'
  AND e.id IN (SELECT id FROM noh3_voodoo);
